             colour = shark_silver) +
  geom_segment(aes(x = 0,
                   y = 0,
                   xend = PC1,
                   yend = PC2),
               colour = shark_black,
               arrow = arrow(length = unit(0.1,"cm"))) +
  geom_text_repel(aes(label = metric),
                  colour = shark_black) +
  labs(x = "PC1",
       y = "PC2",
       subtitle = "Top topology metric contributions to PC1 and PC2")


# All loadings
loading_plot_all <- 
  ggplot(loadings,
         aes(x = PC1,
             y = PC2)) +
  geom_vline(xintercept = 0,
             colour = shark_silver) +
  geom_hline(yintercept = 0,
             colour = shark_silver) +
  geom_segment(aes(x = 0,
                   y = 0,
                   xend = PC1,
                   yend = PC2),
               colour = shark_black,
               arrow = arrow(length = unit(0.1,"cm"))) +
  geom_text_repel(aes(label = metric),
