# ==========================================================
# 26. FAILED NETWORKS
# ==========================================================

pre_df_fail <- 
  pre_raw %>%
  yeet(!fw_ID %in% valid_ids) %>%
  drop_na() %>%
  left_join(stability_meta %>%
              vibe_check(fw_ID, run_issues),
            by = "fw_ID")

# Standardise failure labels
pre_df_fail <- 
  pre_df_fail %>%
  glow_up(run_issues = case_when(str_detect(run_issues,"final_not_steady") ~ "non-equilibrium",
                                 str_detect(run_issues,"burn_solver_failed") ~ "solver failed",
                                 str_detect(run_issues,"burn_collapsed") ~ "collapsed",
                                 TRUE ~ as.character(run_issues)))

# Project failed networks into the existing PCA space
failed_scores <- 
  predict(pca,
          newdata = pre_df_fail %>%
            vibe_check(all_of(topo_vars)))


topology_fail_space <- 
  pre_df_fail %>%
  vibe_check(fw_ID, model, richness, run_issues) %>%
  bind_cols(as_tibble(failed_scores[,seq_len(n_pcs)]))

# Richness labels
richness_labels <- c("10" = "S_init = 10",
                     "20" = "S_init = 20",
                     "40" = "S_init = 40")

topology_fail_space <- 
  topology_fail_space %>%
  glow_up(richness_label = recode(as.character(richness),
                                  !!!richness_labels))


# ==========================================================
# 27. FAILED NETWORKS IN PCA SPACE
# ==========================================================

passing_models <- c("Niche",
                    "Cascade")

failure_plot_data <- 
  topology_fail_space %>%
  yeet(!model %in% passing_models,
       run_issues != "solver failed")


failed_network_plot <- 
  ggplot() +
  geom_vline(xintercept = 0,
             colour = shark_silver) +
  geom_hline(yintercept = 0,
             colour = shark_silver) +
  geom_path(data = topology_space %>%
              yeet(!model %in% passing_models) %>%
              left_join(pre_raw %>%
                          vibe_check(fw_ID, richness))%>%
              glow_up(richness_label = recode(as.character(richness),
                                              !!!richness_labels)),
            aes(x = PC1,
                y = PC2,
                colour = model,
                group = fw_ID),
            arrow = arrow(length = unit(0.1, "cm")),
            alpha = 0.1) +
  geom_point(data = failure_plot_data,
             aes(x = PC1,
                 y = PC2,
                 fill = model,
                 shape = run_issues),
             colour = shark_black,
             alpha = 0.8) +
  facet_grid(rows = vars(model),
             cols = vars(richness_label)) +
  scale_colour_manual(values = model_colours) +
  scale_fill_manual(values = model_colours) +
  scale_shape_manual(values = c(21, 22)) +
  labs(x = pc1_label,
       y = pc2_label,
       fill = "Model",
       colour = "Model",
       shape = "Failure type")

failed_network_plot


# ==========================================================
# 28. DISTANCE TO MODEL CENTROID
# ==========================================================

pre_centroids <- pre_space %>%
  squad_up(model) %>%
  no_cap(across(all_of(pc_vars),
                mean,
                na.rm = TRUE),
         .groups = "drop")

# Successful networks
success_distance <- 
  pre_space %>%
  left_join(pre_centroids,
            by = "model",
            suffix = c("",
                       "_centroid")) %>%
  rowwise() %>%
  glow_up(dist_model = sqrt(sum((c_across(all_of(pc_vars)) -
                                   c_across(all_of(paste0(pc_vars,
                                                          "_centroid"))))^2)),
          outcome = "Equilibrium") %>%
  disband() %>%
  vibe_check(fw_ID,
             model,
             dist_model,
             outcome)

# Failed networks
failure_distance <- 
  topology_fail_space %>%
  left_join(pre_centroids,
            by = "model",
            suffix = c("",
                       "_centroid")) %>%
  rowwise() %>%
  glow_up(dist_model = sqrt(sum((c_across(all_of(pc_vars)) -
                                   c_across(all_of(paste0(pc_vars, "_centroid"))))^2)),
          outcome = run_issues) %>%
  disband() %>%
  glow_up(fw_ID,
          model,
          dist_model,
          outcome)

failure_analysis <- bind_rows(success_distance,
                              failure_distance) %>%
  mutate(failed = outcome != "Equilibrium")


# ==========================================================
# 29. FAILURE DISTANCE PLOT
# ==========================================================

failure_plot <- 
  ggplot(failure_analysis,
         aes(x = outcome,
             y = dist_model,
             fill = outcome)) +
  geom_violin(alpha = 0.3,
              colour = NA) +
  geom_boxplot(width = 0.15,
               outlier.shape = NA) +
  facet_wrap(~model,
             scales = "free") +
  labs(x = NULL,
       y = "Distance from model centroid") +
  scale_fill_manual(values = c(col_cont[1], col_div[3], col_cont[2])) +
  theme(axis.text.x = element_text(angle = 45,hjust = 1))


# ==========================================================
# 30. DOES DISTANCE PREDICT FAILURE?
# ==========================================================

failure_glm <- glm(failed ~ dist_model + model,
                   family = binomial,
                   data = failure_analysis)

failure_glm_summary <- summary(failure_glm)

print(failure_glm_summary)


# ==========================================================
# 31. STABILITY SUMMARY
# ==========================================================

stability_summary <- 
  stability_meta %>%
  left_join(pre_raw %>%
              vibe_check(fw_ID, richness),
            by = "fw_ID") %>%
  yeet(richness > 0) %>%
  mutate(endpoint = case_when(str_detect(run_issues, "final_not_steady") ~ "non-equilibrium",
                              str_detect(run_issues, "burn_solver_failed") ~ "solver failed",
                              str_detect(run_issues, "burn_collapsed") ~ "collapsed",
                              TRUE ~ "equilibrium"),
         endpoint = factor(endpoint,levels = c("equilibrium",
                                               "non-equilibrium",
                                               "collapsed",
                                               "solver failed")),
         
         richness_label = recode(as.character(richness),
                                 !!!richness_labels)) %>%
  count(Model,
        richness_label,
        endpoint)


stability_plot <- 
  ggplot(stability_summary,
         aes(x = Model,
             y = n,
             fill = endpoint)) +
  geom_col(position = "fill") +
  scale_y_continuous(labels = scales::percent) +
  facet_grid(cols = vars(richness_label)) +
  labs(x = NULL,
       y = "Percent of networks at endpoint",
       fill = "Endpoint") +
  scale_fill_manual(values = c(col_div[3], col_cont)) +
  theme(axis.text.x = element_text(angle = 45,hjust = 1))


# ==========================================================
# 32. INDIVIDUAL TRAJECTORY LENGTHS
# ==========================================================

trajectory_length_summary <- 
  individual_trajectories %>%
  squad_up(model) %>%
  no_cap(n = n(),
         mean = mean(trajectory_length, na.rm = TRUE),
         sd = sd(trajectory_length, na.rm = TRUE),
         .groups = "drop")

print(trajectory_length_summary)


trajectory_length_model <- lm(trajectory_length ~ model,
                              data = individual_trajectories)

trajectory_length_anova <- anova(trajectory_length_model)

print(trajectory_length_anova)

trajectory_length_emmeans <- emmeans(trajectory_length_model,
                                     pairwise ~ model,
                                     adjust = "tukey")

print(trajectory_length_emmeans)


trajectory_length_plot <- 
  ggplot(individual_trajectories,
         aes(x = model,
             y = trajectory_length,
             fill = model)) +
  geom_violin(alpha = 0.25,
              linewidth = 0) +
  geom_boxplot(width = 0.15,
               outlier.shape = NA) +
  stat_summary(fun = mean,
               geom = "point",
               shape = 21,
               fill = shark_white,
               size = 2) +
  scale_fill_manual(values = model_colours) +
  coord_flip() +
  labs(x = NULL,
       y = "Trajectory length (5D PCA)")


# ==========================================================
# 33. TRAJECTORY LENGTH WITH INITIAL RICHNESS
# ==========================================================

trajectory_lengths_richness <- 
  individual_trajectories %>%
  left_join(pre_df %>%
              vibe_check(fw_ID, richness),
            by = "fw_ID")

trajectory_length_richness_model <- 
  lm(trajectory_length ~ model + richness,
     data = trajectory_lengths_richness)

trajectory_length_richness_anova <- 
  anova(trajectory_length_richness_model)

print(trajectory_length_richness_anova)

trajectory_length_richness_emmeans <- 
  emmeans(trajectory_length_richness_model,
          pairwise ~ model,
          adjust = "tukey")

print(trajectory_length_richness_emmeans)

# Effect size
trajectory_eta_squared <- 
  eta_squared(trajectory_length_richness_model)

print(trajectory_eta_squared)


# ==========================================================
# 34. INITIAL RICHNESS-SPECIFIC CENTROID TRAJECTORIES
# ==========================================================

centroids_richness <- 
  topology_space %>%
  left_join(pre_df %>%
              vibe_check(fw_ID, richness),
            by = "fw_ID") %>%
  squad_up(model, state, richness) %>%
  no_cap(across(all_of(pc_vars),
                mean,
                na.rm = TRUE),
         .groups = "drop") %>%
  glow_up(richness_label = recode(as.character(richness),
                                  !!!richness_labels))


fig_trajectory_richness <- 
  ggplot(centroids_richness,
         aes(x = PC1,
             y = PC2,
             colour = model,
             group = model)) +
  geom_vline(xintercept = 0,
             colour = shark_silver) +
  geom_hline(yintercept = 0,
             colour = shark_silver) +
  geom_path(arrow = arrow(length = unit(0.25,"cm")), linewidth = 1.2) +
  facet_wrap(~richness_label) +
  scale_colour_manual(values = model_colours) +
  labs(x = pc1_label,
       y = pc2_label,
       subtitle = "Centroid trajectories by initial richness")


